// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {PrivatePool} from "../src/PrivatePool.sol";

contract InvMutTest is Test {
    PrivatePool c;

    function setUp() public {
        c = new PrivatePool(address(this), address(this), address(this));
    }

    function testFuzz_property(address baseTokenArg, address nftArg) public {
        vm.assume(baseTokenArg != address(0));
        vm.assume(baseTokenArg != nftArg);
        vm.assume(baseTokenArg != address(c));

        c.initialize(
            baseTokenArg,
            nftArg,
            uint128(bound(uint256(uint128(1e18)), 1, type(uint128).max)),
            uint128(bound(uint256(uint128(2e18)), 1, type(uint128).max)),
            1e3,
            100,
            bytes32(0),
            false,
            false
        );

        assertTrue(c.baseToken() == baseTokenArg, "baseToken must equal the _baseToken passed to initialize");
    }
}
